# mlcuddidl: OCaml bindings of the CUDD decision diagram library (the copy
# it bundles), generated by camlidl (libcudd_caml.a).  Its Makefile builds
# CUDD with CUDD's configure, then turns the .idl files into C with m4,
# camlidl and sed: the C files come from the opam build directory when the
# switch kept it, otherwise they are regenerated with the host tools.  CUDD
# is configured for the target (sizes of pointers and longs).

SOURCE=opam:mlcuddidl
DEPENDS=camlidl

build() {
  local cudd mods m objs= c
  cudd=$(make_var . CUDDDIR 2>/dev/null || true)
  [ -n "$cudd" ] || cudd=$(ls -d cudd-* | head -1)
  [ -d "$cudd" ] || die "mlcuddidl: no CUDD sources"
  [ -f Makefile.config ] || cp Makefile.config.model Makefile.config
  mods=$(make_var . IDLMODULES)
  [ -n "$mods" ] || die "mlcuddidl: no IDLMODULES in the Makefile"
  for m in $mods; do
    [ -f "${m}_caml.c" ] && continue
    log "regenerating ${m}_caml.c with camlidl"
    make "$m.ml" CAMLIDL="$HOST_BIN/camlidl" CAML_DIR="$PREFIX/lib/ocaml" >&2 \
      || die "mlcuddidl: camlidl failed on $m.idl"
  done

  log "configure CUDD (emconfigure)"
  # the files of opam's sources are dated by their extraction, a few ms
  # apart: make would run automake again
  find "$cudd" -exec touch -r "$cudd/configure" {} +
  rm -rf cuddsrc-wasm; mkdir cuddsrc-wasm
  ( cd cuddsrc-wasm && emconfigure "../$cudd/configure" --host=none --srcdir="../$cudd" \
      --prefix="$PWD/../cuddbld-wasm" --disable-shared --enable-static \
      --disable-dependency-tracking DOXYGEN= CFLAGS="$CFLAGS" ) > configure.log 2>&1 \
    || { tail -30 configure.log; die "CUDD configure failed"; }
  log "make CUDD"
  emmake make -C cuddsrc-wasm -j"$NPROC" install > make.log 2>&1 || { tail -30 make.log; die "CUDD make failed"; }

  local inc="-I$cudd -I$cudd/st -I$cudd/mtr -I$cudd/epd -I$cudd/util -I$cudd/cudd -Icuddsrc-wasm"
  for c in cuddaux*.c $(for m in $mods; do echo "${m}_caml.c"; done) cudd_caml.c; do
    # shellcheck disable=SC2086
    stub_cc "$c" -I. $inc || die "mlcuddidl: cannot compile $c"
    objs="$objs ${c%.c}.o"
  done
  # the CUDD objects go in the stub archive, as in the native one
  mkdir -p cuddobjs && ( cd cuddobjs && "$EMAR" x ../cuddbld-wasm/lib/libcudd.a )
  # shellcheck disable=SC2086
  mklib cudd_caml $objs cuddobjs/*.o
  install_lib libcudd_caml.a
  link_flags cudd_caml "-lcamlidl"
  provides mlcuddidl cudd_caml
}
